// Anonymous live presence and idempotent started-life counter. No character data is sent.
const BirthCounter=(()=>{
 const base='https://fantasy-life-birth-counter.prompt-buddy-cloudflare.workers.dev',endpoint=base+'/api/births',prefix='fantasy-birth-pending:',visitorKey='fantasy-online-visitor-v1';
 const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
 let total=null,online=null,flushing=null,socket=null,started=false,retry=null,retries=0,lastMessage=0,mode='connecting',visitor='';
 const text=s=>typeof GameLanguage!=='undefined'?GameLanguage.text(s):s;
 const visible=()=>document.visibilityState==='visible';
 function identity(){try{const saved=localStorage.getItem(visitorKey);if(uuid.test(saved||''))return saved;const value=crypto.randomUUID();localStorage.setItem(visitorKey,value);return value}catch{return globalThis.crypto?.randomUUID?.()||''}}
 function pending(){try{const ids=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k?.startsWith(prefix)&&uuid.test(k.slice(prefix.length)))ids.push(k.slice(prefix.length))}return ids}catch{return []}}
 function mount(){if(document.querySelector('#worldLiveStats'))return;const bar=document.createElement('section');bar.id='worldLiveStats';bar.className='world-live-stats';bar.setAttribute('aria-label',text('สถิติผู้เล่นและชีวิตในโลกนี้'));bar.setAttribute('data-no-localize','');bar.innerHTML='<div class="live-metric"><span class="live-dot" aria-hidden="true"></span><span data-live-label></span><strong data-online-count>—</strong><span data-online-unit></span></div><div class="live-metric"><span data-total-label></span><strong data-birth-count>—</strong><span data-birth-unit></span></div><small data-live-status role="status"></small>';document.querySelector('header')?.insertAdjacentElement('afterend',bar)}
 function paint(){mount();const format=n=>n===null?'—':n.toLocaleString(document.documentElement.lang==='en'?'en-US':'th-TH');document.querySelectorAll('[data-online-count]').forEach(e=>e.textContent=format(online));document.querySelectorAll('[data-birth-count]').forEach(e=>e.textContent=format(total));const bar=document.querySelector('#worldLiveStats');if(!bar)return;bar.dataset.connection=mode;bar.querySelector('[data-live-label]').textContent=text('ออนไลน์ตอนนี้');bar.querySelector('[data-online-unit]').textContent=text('คน');bar.querySelector('[data-total-label]').textContent=text('ชีวิตที่เกิดแล้ว');bar.querySelector('[data-birth-unit]').textContent=text('ชีวิต');bar.querySelector('[data-live-status]').textContent=text({live:'เรียลไทม์',connecting:'กำลังเชื่อมต่อ',retry:'กำลังเชื่อมต่อใหม่',poll:'อัปเดตเป็นระยะ',offline:'ออฟไลน์'}[mode]);bar.querySelector('[data-online-count]').title=text('นับเบราว์เซอร์ที่เปิดหน้าเกมอยู่ หลายแท็บในเบราว์เซอร์เดียวกันนับครั้งเดียว');bar.querySelector('[data-birth-count]').title=text('นับเมื่อกดใช้ชีวิตชาตินี้ เริ่มนับตั้งแต่ติดตั้งตัวนับ');}
 function apply(v){if(Number.isSafeInteger(v.total)&&v.total>=0)total=total===null?v.total:Math.max(total,v.total);if(Number.isSafeInteger(v.online)&&v.online>=0)online=v.online;paint()}
 async function update(){try{const r=await fetch(base+'/api/stats',{cache:'no-store'});if(!r.ok)throw Error();const v=await r.json();if(!socket||socket.readyState!==WebSocket.OPEN)mode='poll';apply(v)}catch{try{const r=await fetch(endpoint,{cache:'no-store'});if(r.ok)apply(await r.json())}catch{}paint()}}
 async function doFlush(){for(const id of pending()){try{const r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({lifeId:id})});if(!r.ok)break;const v=await r.json();if(!Number.isSafeInteger(v.total)||v.total<0)break;apply(v);localStorage.removeItem(prefix+id)}catch{break}}if(!socket||socket.readyState!==WebSocket.OPEN)await update()}
 function flush(){if(!flushing)flushing=doFlush().finally(()=>{flushing=null});return flushing}
 function recordNewLife(s){if(!globalThis.crypto?.randomUUID)return;if(!uuid.test(s.birthCounterId||''))s.birthCounterId=crypto.randomUUID();try{localStorage.setItem(prefix+s.birthCounterId,'1')}catch{}void flush().then(()=>{if(pending().includes(s.birthCounterId))void flush()})}
 function send(type){if(socket?.readyState===WebSocket.OPEN)try{socket.send(JSON.stringify({type,visible:visible()}))}catch{}}
 function reconnect(){if(retry!==null||!started)return;mode=navigator.onLine?'retry':'offline';online=null;paint();retry=setTimeout(()=>{retry=null;connect()},Math.min(30000,1000*2**Math.min(retries++,5))+Math.random()*500)}
 function connect(){if(!visitor||!navigator.onLine){reconnect();return}if(socket&&socket.readyState<2)return;mode='connecting';paint();try{const ws=new WebSocket(base.replace(/^http/,'ws')+'/api/live?visitor='+encodeURIComponent(visitor)+'&visible='+(visible()?'1':'0'));socket=ws;ws.onopen=()=>{if(socket!==ws)return;lastMessage=Date.now();retries=0;send('heartbeat');void flush()};ws.onmessage=e=>{if(socket!==ws)return;let v;try{v=JSON.parse(e.data)}catch{return}if(v?.type!=='stats'||!Number.isSafeInteger(v.online)||!Number.isSafeInteger(v.total))return;lastMessage=Date.now();mode='live';apply(v)};ws.onclose=()=>{if(socket!==ws)return;socket=null;reconnect()};ws.onerror=()=>{if(socket===ws)ws.close()}}catch{socket=null;reconnect()}}
 function start(){if(started)return;started=true;visitor=identity();paint();connect();void flush();setInterval(()=>{if(socket?.readyState===WebSocket.OPEN){send('heartbeat');if(Date.now()-lastMessage>70000){socket.close();online=null;mode='retry';paint()}}else if(visible())void update()},25000);setInterval(()=>{if(visible()&&pending().length)void flush()},30000);document.addEventListener('visibilitychange',()=>{send('visibility');if(visible()){connect();void flush()}});window.addEventListener('online',()=>{if(retry!==null){clearTimeout(retry);retry=null}connect();void flush()});window.addEventListener('offline',()=>{mode='offline';online=null;paint();socket?.close()});window.addEventListener('pagehide',()=>{socket?.close(1000,'Leaving page')});window.addEventListener('pageshow',()=>{connect()});new MutationObserver(()=>paint()).observe(document.documentElement,{attributes:true,attributeFilter:['lang']})}
 return {recordNewLife,update,flush,paint,start};
})();
